int probe_ati_remote_wonder(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct ati_remote_dev *dev;
    int retval = -ENOMEM;

    if (!interface || !id)
        return -EINVAL;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->interface = interface;
    dev->udev = udev;

    if (udev->actconfig->desc.bNumInterfaces < 2) {
        kfree(dev);
        return -ENODEV;
    }

    if (!interface->cur_altsetting->endpoint ||
        !interface->cur_altsetting->endpoint[1]) {
        kfree(dev);
        return -ENODEV;
    }

    usb_set_intfdata(interface, dev);
    dev->interface_id = id->driver_info;

    usb_fill_int_urb(dev->urb[0], udev,
                     usb_rcvintpipe(udev, 0x81),
                     dev->in_buffer[0], sizeof(dev->in_buffer[0]),
                     ati_remote_irq, dev, 100);
    usb_fill_int_urb(dev->urb[1], udev,
                     usb_rcvintpipe(udev, 0x82),
                     dev->in_buffer[1], sizeof(dev->in_buffer[1]),
                     ati_remote_irq, dev, 100);

    usb_fill_int_urb(dev->urb[2], udev,
                     usb_sndintpipe(udev, 0x02),
                     dev->out_buffer, sizeof(dev->out_buffer),
                     ati_remote_out_irq, dev, 100);

    dev->usbdev = udev;

    if (usb_driver_claim_interface(&ati_remote_driver, interface, dev)) {
        kfree(dev);
        return -ENODEV;
    }

    if (sysfs_create_group(&dev->dev->kobj, &ati_remote_attr_group)) {
        usb_free_urb(dev->urb[0]);
        usb_free_urb(dev->urb[1]);
        usb_free_urb(dev->urb[2]);
        kfree(dev);
        return -ENOMEM;
    }

    dev->enabled = 1;
    device_init_wakeup(&dev->dev->dev, 1);

    return 0;
}

int probe_ati_remote_wonder(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct ati_dev *dev;
    int interface_num, error;

    if (interface == NULL || id == NULL)
        return -EINVAL;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    interface_num = interface->cur_altsetting->desc.bInterfaceNumber;
    if (interface_num != 0) {
        kfree(dev);
        return -ENODEV;
    }

    if (interface->num_altsetting < 1) {
        kfree(dev);
        return -ENODEV;
    }

    iface_desc = interface->cur_altsetting;
    if (iface_desc->desc.bNumEndpoints < 1) {
        kfree(dev);
        return -ENODEV;
    }

    endpoint = &iface_desc->endpoint[0].desc;
    if (!usb_endpoint_is_int_in(endpoint)) {
        kfree(dev);
        return -ENODEV;
    }

    dev->udev = usb_get_dev(interface_to_usbdev(interface));
    dev->interface = interface;
    dev->endpoint = endpoint;
    dev->buffer = usb_buffer_alloc(dev->udev, 64, GFP_KERNEL, &dev->dma_handle);
    if (!dev->buffer) {
        usb_put_dev(dev->udev);
        kfree(dev);
        return -ENOMEM;
    }

    usb_fill_int_urb(dev->urb,
                     dev->udev,
                     usb_rcvintpipe(dev->udev, endpoint->bEndpointAddress),
                     dev->buffer,
                     64,
                     ati_irq,
                     dev,
                     endpoint->bInterval);

    error = usb_register_dev(dev);
    if (error) {
        usb_buffer_free(dev->udev, 64, dev->buffer, dev->dma_handle);
        usb_put_dev(dev->udev);
        kfree(dev);
        return error;
    }

    error = sysfs_create_group(&dev->interface->dev.kobj, &ati_attr_group);
    if (error) {
        usb_deregister_dev(dev);
        usb_buffer_free(dev->udev, 64, dev->buffer, dev->dma_handle);
        usb_put_dev(dev->udev);
        kfree(dev);
        return error;
    }

    usb_set_intfdata(interface, dev);
    dev->enabled_wakeup = 1;

    return 0;
}

int ati_remote_wonder_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct ati_remote_dev *dev;
    int i, retval = -ENOMEM;

    // Check if the first interface is valid
    iface_desc = &interface->cur_altsetting[0];
    if (!iface_desc) {
        return -EINVAL;
    }

    // Allocate memory for the device structure
    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev) {
        return -ENOMEM;
    }

    // Verify that the device has at least two interfaces and each has an endpoint
    if (iface_desc->desc.bNumEndpoints < 1) {
        goto error;
    }

    // Claim the second interface
    if (usb_set_interface(interface->udev, 1, 0)) {
        goto error;
    }

    // Initialize URBs
    for (i = 0; i < NR_URBS; i++) {
        dev->urb[i] = usb_alloc_urb(0, GFP_KERNEL);
        if (!dev->urb[i]) {
            goto error;
        }
    }

    // Set up the device
    usb_fill_int_urb(dev->urb[0], interface->udev, usb_rcvintpipe(interface->udev, endpoint->bEndpointAddress),
                     dev->inbuf, IN_BUF_SIZE, ati_remote_irq, dev, endpoint->bInterval);

    // Create a sysfs group for attributes
    if (sysfs_create_group(&interface->dev.kobj, &ati_remote_attr_group)) {
        goto error;
    }

    // Set the interface data and enable remote wakeup
    usb_set_intfdata(interface, dev);
    device_init_wakeup(&interface->dev, 1);

    return 0;

error:
    kfree(dev);
    return retval;
}

int ati_remote_wonder_init(struct usb_interface *interface, const struct usb_device_id *id)
{
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct ati_dev *dev;
    int i, retval = -ENOMEM;

    if (!interface)
        return -EINVAL;

    dev = kzalloc(sizeof(struct ati_dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(interface_to_usbdev(interface));
    dev->interface = interface;

    iface_desc = &interface->cur_altsetting[0];
    if (iface_desc->desc.bNumEndpoints < 1)
        goto error;

    endpoint = &iface_desc->endpoint[0].desc;
    dev->ep_out = endpoint->bEndpointAddress;

    iface_desc = &interface->cur_altsetting[1];
    if (iface_desc->desc.bNumEndpoints < 1)
        goto error;

    endpoint = &iface_desc->endpoint[0].desc;
    dev->ep_in = endpoint->bEndpointAddress;

    retval = usb_set_interface(dev->udev, 1, 0);
    if (retval < 0)
        goto error;

    usb_fill_int_urb(dev->urb_in, dev->udev,
                     usb_rcvintpipe(dev->udev, dev->ep_in),
                     dev->inbuf, sizeof(dev->inbuf),
                     ati_remote_wonder_irq, dev, 1);

    usb_fill_int_urb(dev->urb_out, dev->udev,
                     usb_sndintpipe(dev->udev, dev->ep_out),
                     dev->outbuf, sizeof(dev->outbuf),
                     NULL, dev, 1);

    usb_set_intfdata(interface, dev);

    if (sysfs_create_group(&interface->dev.kobj, &ati_dev_attr_group))
        goto error;

    return 0;

error:
    if (dev)
        kfree(dev);
    return retval;
}

int probe_ati_remote_wonder(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct ati_remote_dev *dev;
    int rc;

    if (!interface) {
        return -EINVAL;
    }

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev) {
        return -ENOMEM;
    }

    dev->udev = udev;
    dev->interface = interface;

    if (udev->actconfig->interface[1].altsetting[0].desc.bNumEndpoints < 1) {
        kfree(dev);
        return -ENODEV;
    }

    rc = usb_set_interface(udev, 1, 0);
    if (rc < 0) {
        kfree(dev);
        return rc;
    }

    dev->ep = &udev->actconfig->interface[1].altsetting[0].endpoint[0].desc;

    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb) {
        kfree(dev);
        return -ENOMEM;
    }

    usb_fill_int_urb(dev->urb, udev, usb_rcvintpipe(udev, dev->ep->bEndpointAddress),
                     dev->data, sizeof(dev->data), ati_remote_irq, dev, dev->ep->bInterval);

    rc = sysfs_create_group(&interface->dev.kobj, &ati_remote_attr_group);
    if (rc < 0) {
        usb_free_urb(dev->urb);
        kfree(dev);
        return rc;
    }

    usb_set_intfdata(interface, dev);
    dev->enabled_wakeup = 1;

    return 0;
}
